create table public.classroom_observations (id integer generated by default as identity not null, school character varying(255), teacher character varying(255), class_section character varying(100), subject character varying(100), topic character varying(255), visit_date date, duration character varying(50), students_present integer, print_displayed character varying(10), academic_mentor character varying(255), rubric_json jsonb, flow_of_class text, high_points text, recommendations text, pdf_url text, created_at timestamp without time zone default CURRENT_TIMESTAMP, evidence_links text);
create table public.portal_actions (id text not null, school text not null, teacher text default ''::text not null, finding text not null, evidence text default ''::text not null, cause text default ''::text not null, cause_confidence text default 'Hypothesis'::text not null, action text not null, owner text not null, owner_role text default 'Teacher'::text not null, due_date date not null, success_criterion text not null, support text default ''::text not null, priority text default 'Normal'::text not null, status text default 'Open'::text not null, verification text default ''::text not null, verified_by text default ''::text not null, verified_at timestamp with time zone, created_by text not null, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null);
create table public.portal_action_history (id bigint generated by default as identity not null, action_id text not null, actor text not null, snapshot jsonb not null, recorded_at timestamp with time zone default now() not null);
create table public.portal_evidence_reviews (record_id text not null, school text not null, teacher text not null, status text not null, feedback text not null, next_step text default ''::text not null, reviewer text not null, updated_at timestamp with time zone default now() not null);
create table public.portal_import_runs (id text not null, source text not null, input_rows integer not null, inserted_rows integer not null, skipped_rows integer not null, actor text not null, created_at timestamp with time zone default now() not null);
create table public.portal_contacts (school text not null, entity_type text not null, name text default ''::text not null, phone text default ''::text not null, updated_at timestamp with time zone default now() not null);
create table public.portal_call_logs (id text not null, school text not null, payload jsonb not null, created_at timestamp with time zone default now() not null, archived_at timestamp with time zone, ticket_id uuid, completed_at timestamp with time zone);
create table public.portal_tickets (id uuid default gen_random_uuid() not null, school text not null, title text not null, description text not null, status text default 'Open'::text not null, priority text default 'Normal'::text not null, opened_on date not null, next_action_on date, resolution text default ''::text not null, resolved_at timestamp with time zone, archived_at timestamp with time zone, version bigint default 1 not null, created_by text not null, updated_by text not null, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null);
create table public.teacher_records (id bigint generated by default as identity not null, created_at timestamp with time zone default now(), "State_Zone" character varying(100) default 'Madhya Pradesh (MP)'::character varying, "Uploaded_By" character varying(150), "Institution" character varying(200), "Center" character varying(200), "FirstName" character varying(100), "LastName" character varying(100), "FullName" character varying(200), "Role" character varying(50) default 'teacher'::character varying, "Type" character varying(50) default 'lessonDelivery'::character varying, "Grade" character varying(50), "Subject" character varying(100), "Book" text, "StartTime" timestamp without time zone, "EndTime" timestamp without time zone, "Duration_Min" numeric(8,2) default 0.0, "Voice_Note_Link" text, "Lesson_Plan_Picture" text, "Video_Evidence_1" text, "Video_Evidence_2" text, "Video_Evidence_3" text, "Writing_Sample_Link" text, "Phonics_Evidence_Link" text, "Portfolio_Evidence_Link" text, "Assessment_Score_Pct" numeric(5,2), "Record_Hash" text, "Student_Assessment_Link" text, submitted_at timestamp without time zone default CURRENT_TIMESTAMP, "Event_Pictures_Link" text, "Section" text, implementation_date date, submission_id text, implementation_id text, lesson_reflection text, materials_notes text, lesson_period_id text, planned_lesson_on date, preparation_saved_at timestamp without time zone, conducted_on date, evidence_submitted_at timestamp without time zone, lesson_stage text, lesson_version integer default 0 not null, last_evidence_update_id text, lesson_evidence_history jsonb default '[]'::jsonb not null);
alter table public.portal_school_plans add constraint portal_school_plans_pkey PRIMARY KEY (school);
alter table public.classroom_observations add constraint classroom_observations_pkey PRIMARY KEY (id);
alter table public.portal_actions add constraint portal_actions_pkey PRIMARY KEY (id);
alter table public.portal_action_history add constraint portal_action_history_pkey PRIMARY KEY (id);
alter table public.portal_evidence_reviews add constraint portal_evidence_reviews_pkey PRIMARY KEY (record_id);
alter table public.portal_import_runs add constraint portal_import_runs_pkey PRIMARY KEY (id);
alter table public.portal_contacts add constraint portal_contacts_pkey PRIMARY KEY (school, entity_type);
alter table public.portal_call_logs add constraint portal_call_logs_pkey PRIMARY KEY (id);
alter table public.portal_tickets add constraint portal_tickets_check CHECK (((status <> 'Resolved'::text) OR (length(TRIM(BOTH FROM resolution)) > 0)));
alter table public.portal_tickets add constraint portal_tickets_check1 CHECK (((status = 'Resolved'::text) OR (next_action_on IS NOT NULL)));
