CREATE OR REPLACE FUNCTION public.school_success_append_lesson_evidence(p_submission text, p_actor text, p_update text, p_version integer, p_conducted date, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare total integer; item jsonb; incoming public.teacher_records%rowtype; current_row public.teacher_records%rowtype; stage text; has_evidence boolean;
begin
 if coalesce(p_submission,'') !~ '^[a-f0-9-]{36}$' or coalesce(p_update,'') !~ '^[a-f0-9-]{36}$' or nullif(p_actor,'') is null or p_version is null or p_version<0 or p_conducted is null or p_conducted>(now() at time zone 'Asia/Kolkata')::date then raise exception 'Invalid lesson update or conducted date';end if;
 if p_rows is null or jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows) not between 1 and 10 then raise exception 'Use 1 to 10 periods';end if;
 perform pg_advisory_xact_lock(hashtext(p_submission),72841903);
 select count(*) into total from public.teacher_records where submission_id=p_submission;
 if total=0 or total<>jsonb_array_length(p_rows) or exists(select from public.teacher_records where submission_id=p_submission and ("Uploaded_By" is distinct from p_actor or lesson_stage is null)) then raise exception 'Lesson access denied';end if;
 if not exists(select from public.teacher_records where submission_id=p_submission and last_evidence_update_id is distinct from p_update) then
 return jsonb_build_object('saved',true,'alreadySaved',true,'submissionId',p_submission,'periods',total,'version',(select max(lesson_version) from public.teacher_records where submission_id=p_submission));end if;
 if exists(select from public.teacher_records where submission_id=p_submission and lesson_version<>p_version) then raise exception 'Lesson changed. Reopen the return link before adding evidence.' using errcode='40001';end if;
 if (select count(distinct value->>'lesson_period_id') from jsonb_array_elements(p_rows))<>total then raise exception 'Repeated or missing period identity';end if;
 for item in select value from jsonb_array_elements(p_rows) loop
 incoming:=jsonb_populate_record(null::public.teacher_records,item);
 select * into current_row from public.teacher_records where submission_id=p_submission and lesson_period_id=incoming.lesson_period_id;
 if not found or incoming."Center" is distinct from current_row."Center" or incoming."FullName" is distinct from current_row."FullName" then raise exception 'Lesson period access denied';end if;
 if nullif(incoming."Voice_Note_Link",'') is not null then raise exception 'Preparation audio cannot be replaced by an evidence update';end if;
 has_evidence:=nullif(concat(incoming."Video_Evidence_1",incoming."Video_Evidence_2",incoming."Video_Evidence_3",incoming."Writing_Sample_Link",incoming."Phonics_Evidence_Link",incoming."Portfolio_Evidence_Link",incoming."Event_Pictures_Link",incoming."Lesson_Plan_Picture"),'') is not null;
 stage:=case when has_evidence or current_row.lesson_stage='evidence_submitted' then 'evidence_submitted' else current_row.lesson_stage end;
 update public.teacher_records set
 "Video_Evidence_1"=public.school_success_merge_evidence("Video_Evidence_1",incoming."Video_Evidence_1"),"Video_Evidence_2"=public.school_success_merge_evidence("Video_Evidence_2",incoming."Video_Evidence_2"),"Video_Evidence_3"=public.school_success_merge_evidence("Video_Evidence_3",incoming."Video_Evidence_3"),
 "Writing_Sample_Link"=public.school_success_merge_evidence("Writing_Sample_Link",incoming."Writing_Sample_Link"),"Phonics_Evidence_Link"=public.school_success_merge_evidence("Phonics_Evidence_Link",incoming."Phonics_Evidence_Link"),"Portfolio_Evidence_Link"=public.school_success_merge_evidence("Portfolio_Evidence_Link",incoming."Portfolio_Evidence_Link"),"Event_Pictures_Link"=public.school_success_merge_evidence("Event_Pictures_Link",incoming."Event_Pictures_Link"),"Lesson_Plan_Picture"=public.school_success_merge_evidence("Lesson_Plan_Picture",incoming."Lesson_Plan_Picture"),
 lesson_evidence_history=case when has_evidence then lesson_evidence_history||jsonb_build_array(jsonb_build_object('id',p_update,'at',now() at time zone 'UTC','conductedOn',p_conducted,'files',jsonb_build_object('Video_Evidence_1',incoming."Video_Evidence_1",'Video_Evidence_2',incoming."Video_Evidence_2",'Video_Evidence_3',incoming."Video_Evidence_3",'Writing_Sample_Link',incoming."Writing_Sample_Link",'Phonics_Evidence_Link',incoming."Phonics_Evidence_Link",'Portfolio_Evidence_Link',incoming."Portfolio_Evidence_Link",'Event_Pictures_Link',incoming."Event_Pictures_Link",'Lesson_Plan_Picture',incoming."Lesson_Plan_Picture"))) else lesson_evidence_history end,
 conducted_on=case when has_evidence then p_conducted else conducted_on end,implementation_date=case when has_evidence then p_conducted else implementation_date end,"StartTime"=case when has_evidence then p_conducted::timestamp else "StartTime" end,"EndTime"=case when has_evidence then p_conducted::timestamp else "EndTime" end,lesson_stage=stage,lesson_version=lesson_version+1,last_evidence_update_id=p_update,evidence_submitted_at=case when has_evidence then now() at time zone 'UTC' else evidence_submitted_at end
 where submission_id=p_submission and lesson_period_id=incoming.lesson_period_id;
 end loop;
 return jsonb_build_object('saved',true,'alreadySaved',false,'submissionId',p_submission,'periods',total,'version',p_version+1,'stage',case when exists(select from public.teacher_records where submission_id=p_submission and lesson_stage='evidence_submitted') then 'evidence_submitted' else current_row.lesson_stage end);
end $function$
;
CREATE OR REPLACE FUNCTION public.school_success_import_usage(p_rows jsonb, p_actor text, p_source text, p_preview boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare item jsonb; rec public.teacher_records%rowtype; identity text; existing_id bigint; inserted_count int:=0; skipped_count int:=0; enriched_count int:=0; changed int; rejected jsonb:='[]'; total int:=0; seen text[]:='{}';
begin
 if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)>20000 then raise exception 'Expected at most 20,000 rows';end if;
 if nullif(trim(p_actor),'') is null then raise exception 'Actor required';end if;
 -- Same advisory lock as the original Streamlit importer; table lock also serializes other writers.
 perform pg_advisory_xact_lock(72841902);
 lock table public.teacher_records in share row exclusive mode;
 for item in select value from jsonb_array_elements(p_rows) loop
 total:=total+1;
 begin
 rec:=jsonb_populate_record(null::public.teacher_records,item);
 if nullif(trim(coalesce(nullif(rec."Center",''),rec."Institution")),'') is null or nullif(trim(rec."FullName"),'') is null or nullif(trim(rec."Type"),'') is null or rec."StartTime" is null or rec."Duration_Min" is null or rec."Duration_Min"<0 or rec."Duration_Min">1440 or rec."EndTime"<rec."StartTime" then raise exception 'Invalid school, teacher, activity, date or duration';end if;
 identity:=public.school_success_usage_key(coalesce(nullif(rec."Center",''),rec."Institution"),rec."FullName",rec."Type",rec."StartTime",rec."EndTime",rec."Duration_Min",rec."Grade",rec."Subject",rec."Book");
 select t.id into existing_id from public.teacher_records t where public.school_success_usage_key(coalesce(nullif(t."Center",''),t."Institution"),coalesce(nullif(t."FullName",''),trim(coalesce(t."FirstName",'')||' '||coalesce(t."LastName",''))),t."Type",t."StartTime",t."EndTime",t."Duration_Min",t."Grade",t."Subject",t."Book")=identity and not (coalesce(t."Type",'')='Classroom Reflection' or coalesce(t."Voice_Note_Link",'')<>'' or coalesce(t."Lesson_Plan_Picture",'')<>'' or coalesce(t."Video_Evidence_1",'')<>'' or coalesce(t."Writing_Sample_Link",'')<>'') order by t.id limit 1;
 if existing_id is not null or identity=any(seen) then
 skipped_count:=skipped_count+1;
 if not p_preview and existing_id is not null then
 update public.teacher_records t set "Book"=coalesce(nullif(t."Book",''),nullif(rec."Book",'')),"Grade"=coalesce(nullif(t."Grade",''),nullif(rec."Grade",'')),"Subject"=coalesce(nullif(t."Subject",''),nullif(rec."Subject",'')) where t.id=existing_id and ((coalesce(t."Book",'')='' and coalesce(rec."Book",'')<>'') or (coalesce(t."Grade",'')='' and coalesce(rec."Grade",'')<>'') or (coalesce(t."Subject",'')='' and coalesce(rec."Subject",'')<>''));
 get diagnostics changed=row_count;enriched_count:=enriched_count+changed;
 end if;
 else
 inserted_count:=inserted_count+1;
 if not p_preview then
 insert into public.teacher_records("Institution","Center","FirstName","LastName","FullName","Role","Type","Grade","Subject","Book","StartTime","EndTime","Duration_Min","Uploaded_By","State_Zone","Record_Hash") values(rec."Institution",rec."Center",rec."FirstName",rec."LastName",rec."FullName",rec."Role",rec."Type",rec."Grade",rec."Subject",rec."Book",rec."StartTime",rec."EndTime",rec."Duration_Min",p_actor,coalesce(nullif(rec."State_Zone",''),'Madhya Pradesh (MP)'),'web-session:'||identity);
 end if;
 end if;
 seen:=array_append(seen,identity);
 exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range or raise_exception then rejected:=rejected||jsonb_build_array(jsonb_build_object('file',item->>'_source_file','row',item->'_excel_row','reason',sqlerrm));
 end;
 end loop;
 if not p_preview then insert into public.portal_import_runs(id,source,input_rows,inserted_rows,skipped_rows,actor) values(gen_random_uuid()::text,left(p_source,2000),total,inserted_count,skipped_count,p_actor);end if;
 return jsonb_build_object('preview',p_preview,'total',total,'inserted',case when p_preview then 0 else inserted_count end,'newRows',inserted_count,'skipped',skipped_count,'enriched',enriched_count,'rejected',rejected);
end;
$function$
;
CREATE OR REPLACE FUNCTION public.school_success_merge_evidence(p_old text, p_new text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select coalesce(string_agg(v,',' order by v),'') from (select distinct v from unnest(string_to_array(concat_ws(',',nullif(p_old,''),nullif(p_new,'')),',')) v where v<>'') s;
$function$
;
CREATE OR REPLACE FUNCTION public.school_success_roster()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$ SELECT coalesce(jsonb_agg(x),'[]'::jsonb) FROM (SELECT DISTINCT coalesce(nullif(trim("Center"),''),"Institution") school, coalesce(nullif(trim("FullName"),''),trim(concat_ws(' ',"FirstName","LastName"))) name FROM public.teacher_records WHERE lower(coalesce("Role",'teacher')) IN ('teacher','teachers') AND coalesce(nullif(trim("Center"),''),"Institution") IS NOT NULL) x; $function$
;
CREATE OR REPLACE FUNCTION public.school_success_save_preparation(p_rows jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare result jsonb; item jsonb; version integer;
begin
 if p_rows is null or jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows) not between 1 and 10 then raise exception 'Use 1 to 10 periods';end if;
 for item in select value from jsonb_array_elements(p_rows) loop
 if coalesce(item->>'lesson_period_id','') !~ '^[a-f0-9-]{36}$' then raise exception 'Invalid period identity';end if;
 end loop;
 if (select count(distinct value->>'lesson_period_id') from jsonb_array_elements(p_rows))<>jsonb_array_length(p_rows) then raise exception 'Repeated period identity';end if;
 result:=public.school_success_submit_evidence(p_rows,p_actor);
 for item in select value from jsonb_array_elements(p_rows) loop
 update public.teacher_records set lesson_period_id=item->>'lesson_period_id',planned_lesson_on=implementation_date::date,preparation_saved_at=submitted_at,lesson_stage='preparation_saved'
 where submission_id=p_rows->0->>'submission_id' and implementation_id=item->>'implementation_id' and lesson_stage is null;
 end loop;
 select max(lesson_version) into version from public.teacher_records where submission_id=p_rows->0->>'submission_id';
 return result||jsonb_build_object('stage','preparation_saved','version',version);
end $function$
;
CREATE OR REPLACE FUNCTION public.school_success_submit_evidence(p_rows jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare submission text;school text;teacher text;item jsonb;rec public.teacher_records%rowtype;existing int;expected int;period int:=0;
begin
 if p_rows is null or jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows) not between 1 and 10 then raise exception 'Use 1 to 10 periods';end if;
 submission:=p_rows->0->>'submission_id';school:=p_rows->0->>'Center';teacher:=p_rows->0->>'FullName';expected:=jsonb_array_length(p_rows);
 if submission is null or submission !~ '^[a-f0-9-]{36}$' or nullif(school,'') is null or nullif(teacher,'') is null or nullif(p_actor,'') is null then raise exception 'Invalid teacher submission';end if;
 perform pg_advisory_xact_lock(hashtext(submission),72841903);
 select count(*) into existing from public.teacher_records where submission_id=submission;
 if existing>0 then
 if existing<>expected or exists(select from public.teacher_records where submission_id=submission and ("Uploaded_By" is distinct from p_actor or "Center" is distinct from school or "FullName" is distinct from teacher)) then raise exception 'Submission ID belongs to a different submission';end if;
 return jsonb_build_object('saved',true,'submissionId',submission,'periods',existing,'alreadySaved',true);
 end if;
 for item in select value from jsonb_array_elements(p_rows) loop
 rec:=jsonb_populate_record(null::public.teacher_records,item);
 period:=period+1;
 if rec.submission_id is distinct from submission or rec."Center" is distinct from school or rec."FullName" is distinct from teacher or rec.implementation_id is distinct from submission||':'||period::text then raise exception 'Mixed or unordered teacher submissions are not allowed';end if;
 if rec."Type" is distinct from 'Classroom Reflection' or nullif(rec."Grade",'') is null or nullif(rec."Subject",'') is null or nullif(rec."Book",'') is null or rec.implementation_date is null or rec.implementation_id is null or rec.implementation_id !~ ('^'||submission||':[1-9][0-9]?$') then raise exception 'Missing class, subject, topic or lesson date';end if;
 insert into public.teacher_records("Institution","Center","FullName","FirstName","LastName","Role","Type","Grade","Section","Subject","Book","StartTime","EndTime","Duration_Min",implementation_date,submission_id,implementation_id,"Uploaded_By",submitted_at,"Record_Hash","Voice_Note_Link","Lesson_Plan_Picture","Video_Evidence_1","Video_Evidence_2","Video_Evidence_3","Writing_Sample_Link","Phonics_Evidence_Link","Portfolio_Evidence_Link","Event_Pictures_Link",lesson_reflection,materials_notes)
 values(school,school,teacher,rec."FirstName",rec."LastName",'teacher','Classroom Reflection',rec."Grade",rec."Section",rec."Subject",rec."Book",rec.implementation_date::timestamp,rec.implementation_date::timestamp,0,rec.implementation_date,submission,rec.implementation_id,p_actor,now() at time zone 'UTC','web-evidence:'||rec.implementation_id,rec."Voice_Note_Link",rec."Lesson_Plan_Picture",rec."Video_Evidence_1",rec."Video_Evidence_2",rec."Video_Evidence_3",rec."Writing_Sample_Link",rec."Phonics_Evidence_Link",rec."Portfolio_Evidence_Link",rec."Event_Pictures_Link",rec.lesson_reflection,rec.materials_notes);
 end loop;
 return jsonb_build_object('saved',true,'submissionId',submission,'periods',expected,'alreadySaved',false);
end $function$
;
CREATE OR REPLACE FUNCTION public.school_success_usage_key(school text, teacher text, activity text, started timestamp without time zone, ended timestamp without time zone, minutes numeric, grade text, subject text, book text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select pg_catalog.md5(pg_catalog.jsonb_build_array(
 lower(regexp_replace(trim(coalesce(school,'')),'\s+',' ','g')),
 lower(regexp_replace(trim(coalesce(teacher,'')),'\s+',' ','g')),
 case when regexp_replace(lower(coalesce(activity,'')),'[^a-z0-9]','','g') in ('book','books','bookusage','content','contentusage','contentbook') then 'book' when regexp_replace(lower(coalesce(activity,'')),'[^a-z0-9]','','g') in ('lessonplan','lessonpreparation','lessondelivery') then 'lessondelivery' else regexp_replace(lower(coalesce(activity,'')),'[^a-z0-9]','','g') end,
 round(extract(epoch from started)),round(extract(epoch from ended)),round(minutes,2),
 case when ended is null then lower(trim(coalesce(grade,''))) else '' end,
 case when ended is null then lower(trim(coalesce(subject,''))) else '' end,
 case when ended is null then lower(trim(coalesce(book,''))) else '' end
 )::text)
$function$

;
create table public.success_config(key text primary key,value text not null,revision text not null default '');
create table public.success_members(email text primary key,role text not null,school text not null,name text not null);
create table public.success_entries(id text primary key,kind text not null,school text not null,owner text not null,payload text not null,version integer not null default 1,updated text not null);
create table public.success_audit(id text primary key,actor text not null,action text not null,record text not null,created text not null);
create table public.success_school_mappings(source_school text primary key,vision_school_id uuid not null unique references public.literacy_schools(id),approved_by uuid not null,approved_at timestamptz not null default now());
create table public.success_teacher_mappings(source_school text not null references public.success_school_mappings(source_school),source_teacher text not null,vision_user_id uuid not null,approved_by uuid not null,approved_at timestamptz not null default now(),primary key(source_school,source_teacher),unique(source_school,vision_user_id));
create table public.success_import_state(key text primary key,value jsonb not null,updated_at timestamptz not null default now());
create or replace function public.vision_success_local_batch(p_ops jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare item jsonb; n integer; results jsonb='[]'; val text; rev text;
begin
 for item in select * from jsonb_array_elements(p_ops) loop
 n=0;val=item->>'value';rev='';if val is not null then begin rev=coalesce((val::jsonb)->>'revision','');exception when others then rev='';end;end if;
 case item->>'op'
 when 'configPut' then insert into success_config(key,value,revision) values(item->>'key',val,rev) on conflict(key) do update set value=excluded.value,revision=excluded.revision;get diagnostics n=row_count;
 when 'configInsert' then insert into success_config(key,value,revision) values(item->>'key',val,rev) on conflict do nothing;get diagnostics n=row_count;
 when 'configUpdate' then update success_config set value=val,revision=rev where key=item->>'key' and revision=item->>'revision';get diagnostics n=row_count;
 when 'memberPut' then insert into success_members(email,role,school,name) values(item->>'email','teacher',item->>'school',item->>'name') on conflict(email) do update set school=excluded.school,name=excluded.name;get diagnostics n=row_count;
 when 'entryInsert' then insert into success_entries(id,kind,school,owner,payload,updated) values(item->>'id',item->>'kind',item->>'school',item->>'owner',item->>'payload',item->>'updated') on conflict do nothing;get diagnostics n=row_count;
 when 'entryUpdate' then update success_entries set payload=item->>'payload',school=item->>'school',version=version+1,updated=item->>'updated' where id=item->>'id' and version=(item->>'version')::integer;get diagnostics n=row_count;
 when 'auditInsert' then insert into success_audit(id,actor,action,record,created) values(item->>'id',item->>'actor',item->>'action',item->>'record',item->>'created');get diagnostics n=row_count;
 else raise exception 'Unsupported operation';
 end case;
 results=results||jsonb_build_array(jsonb_build_object('meta',jsonb_build_object('changes',n)));
 end loop;return results;
end $$;
create or replace function public.vision_success_reset_sequences() returns void language plpgsql security invoker set search_path=public,pg_temp as $$
declare t text;seq text;m bigint;
begin
foreach t in array array['teacher_records','classroom_observations'] loop
seq=pg_get_serial_sequence('public.'||t,'id');if seq is not null then execute format('select max(id) from public.%I',t) into m;if m is not null then perform setval(seq,m,true);end if;end if;
end loop;
end $$;

